package com.inspect.npc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class NpcInspectCacheTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void readsFreshDiskCache() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		NpcCombatInfo info = info(3028, 1000L);

		cache.put(info).get();
		cache.shutDown();

		NpcInspectCache restored = new NpcInspectCache(new Gson(), directory);
		Optional<NpcCombatInfo> cached = restored.get(3028, 1100L, 7).get();

		assertTrue(cached.isPresent());
		assertEquals(3028, cached.get().getNpcId());
		restored.shutDown();
	}

	@Test
	public void keepsCacheAtExactTtlBoundaryAndExpiresItAfterward() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		long sevenDays = 7L * 24L * 60L * 60L;
		cache.put(info(3028, 1000L)).get();

		assertTrue(cache.get(3028, 1000L + sevenDays, 7).get().isPresent());
		assertFalse(cache.get(3028, 1000L + sevenDays + 1L, 7).get().isPresent());
		cache.shutDown();
	}

	@Test
	public void zeroTtlNeverReturnsCachedEntry() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		cache.put(info(3028, 1000L)).get();

		assertFalse(cache.get(3028, 1000L, 0).get().isPresent());
		cache.shutDown();
	}

	@Test
	public void ignoresExpiredDiskCache() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		NpcCombatInfo info = info(3028, 1000L);

		cache.put(info).get();
		Optional<NpcCombatInfo> cached = cache.get(3028, 1000L + 8L * 24L * 60L * 60L, 7).get();

		assertFalse(cached.isPresent());
		cache.shutDown();
	}

	@Test
	public void ignoresCorruptDiskCache() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		NpcCombatInfo info = info(3028, 1000L);
		cache.put(info).get();
		cache.shutDown();

		Files.write(directory.resolve(info.cacheKey() + ".json"), "{".getBytes(StandardCharsets.UTF_8));

		NpcInspectCache restored = new NpcInspectCache(new Gson(), directory);
		Optional<NpcCombatInfo> cached = restored.get(3028, 1100L, 7).get();

		assertFalse(cached.isPresent());
		restored.shutDown();
	}

	@Test
	public void rejectsDiskPayloadForDifferentNpc() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		Gson gson = new Gson();
		NpcCombatInfo expected = info(3028, 1000L);
		NpcInspectCache cache = new NpcInspectCache(gson, directory);
		cache.put(expected).get();
		cache.shutDown();

		Path payload = directory.resolve(expected.cacheKey() + ".json");
		Files.write(payload, gson.toJson(info(9999, 1000L)).getBytes(StandardCharsets.UTF_8));

		NpcInspectCache restored = new NpcInspectCache(gson, directory);
		Optional<NpcCombatInfo> cached = restored.get(3028, 1100L, 7).get();

		assertFalse(cached.isPresent());
		assertFalse(Files.exists(payload));
		restored.shutDown();
	}

	@Test
	public void rejectsDiskPayloadFromOldCacheSchema() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		Gson gson = new Gson();
		NpcCombatInfo info = info(3028, 1000L);
		NpcInspectCache cache = new NpcInspectCache(gson, directory);
		cache.put(info).get();
		cache.shutDown();

		Path payload = directory.resolve(info.cacheKey() + ".json");
		JsonObject oldPayload = gson.toJsonTree(info).getAsJsonObject();
		oldPayload.remove("cacheSchemaVersion");
		Files.write(payload, gson.toJson(oldPayload).getBytes(StandardCharsets.UTF_8));

		NpcInspectCache restored = new NpcInspectCache(gson, directory);
		Optional<NpcCombatInfo> cached = restored.get(3028, 1100L, 7).get();

		assertFalse(cached.isPresent());
		assertFalse(Files.exists(payload));
		restored.shutDown();
	}

	@Test
	public void ignoresEntireIndexWhenAnyEntryIsCorrupt() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcCombatInfo info = info(3028, 1000L);
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		cache.put(info).get();
		cache.shutDown();

		Path index = directory.resolve("index.json");
		String corruptIndex = "{\"3028\":\"" + info.cacheKey() + "\",\"not-an-id\":\"bad\"}";
		Files.write(index, corruptIndex.getBytes(StandardCharsets.UTF_8));

		NpcInspectCache restored = new NpcInspectCache(new Gson(), directory);
		Optional<NpcCombatInfo> cached = restored.get(3028, 1100L, 7).get();

		assertFalse(cached.isPresent());
		assertFalse(Files.exists(index));
		restored.shutDown();
	}

	@Test
	public void rejectsCacheKeyThatEscapesCacheDirectory() throws Exception
	{
		Path parent = temporaryFolder.newFolder().toPath();
		Path directory = Files.createDirectory(parent.resolve("cache"));
		Path outsideFile = parent.resolve("outside.json");
		Files.write(outsideFile, new Gson().toJson(info(3028, 1000L)).getBytes(StandardCharsets.UTF_8));
		Path indexFile = directory.resolve("index.json");
		Files.write(indexFile, "{\"3028\":\"../outside\"}".getBytes(StandardCharsets.UTF_8));

		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);

		assertFalse(cache.get(3028, 1100L, 7).get().isPresent());
		assertFalse(Files.exists(indexFile));
		assertTrue(Files.exists(outsideFile));
		cache.shutDown();
	}

	@Test
	public void clearRemovesMemoryAndDiskEntries() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcCombatInfo info = info(3028, 1000L);
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		cache.put(info).get();

		cache.clearAsync().get();

		assertFalse(cache.get(3028, 1100L, 7).get().isPresent());
		assertFalse(Files.exists(directory.resolve(info.cacheKey() + ".json")));
		assertFalse(Files.exists(directory.resolve("index.json")));
		cache.shutDown();
	}

	@Test
	public void startupClearRunsBeforeSubsequentCacheReads() throws Exception
	{
		Path directory = temporaryFolder.newFolder().toPath();
		NpcCombatInfo info = info(3028, 1000L);
		NpcInspectCache cache = new NpcInspectCache(new Gson(), directory);
		cache.put(info).get();
		cache.shutDown();

		NpcInspectCache restored = new NpcInspectCache(new Gson(), directory);
		restored.startUp(true);

		assertFalse(restored.get(3028, 1100L, 7).get().isPresent());
		assertFalse(Files.exists(directory.resolve(info.cacheKey() + ".json")));
		assertFalse(Files.exists(directory.resolve("index.json")));
		restored.shutDown();
	}

	private static NpcCombatInfo info(int npcId, long fetchedAt)
	{
		return NpcCombatInfo.builder()
			.npcId(npcId)
			.wikiPage("Goblin")
			.wikiAnchor("Level_2")
			.displayName("Goblin")
			.fetchedAtEpochSecond(fetchedAt)
			.sourceUrl("https://oldschool.runescape.wiki/w/Goblin#Level_2")
			.build();
	}
}

package com.inspect.npc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.inspect.item.ItemInspectInfo;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

public class BankEquipmentRecommendationServiceTest
{
	@Test
	public void emptyInputReturnsPreviewWithoutItemLookups() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		BankEquipmentRecommendationService service = new BankEquipmentRecommendationService((itemId, itemName, ttlDays) ->
		{
			calls.incrementAndGet();
			return CompletableFuture.completedFuture(null);
		});

		EquipmentRecommendation nullItems = service.recommend(stabNpc(), null, 7).get(5, TimeUnit.SECONDS);
		EquipmentRecommendation emptyItems = service.recommend(stabNpc(), Collections.emptyList(), 7).get(5, TimeUnit.SECONDS);

		assertEquals("Stab melee", nullItems.getStyleName());
		assertFalse(nullItems.hasItems());
		assertEquals("Stab melee", emptyItems.getStyleName());
		assertEquals(0, calls.get());
	}

	@Test
	public void duplicateCandidatesMergeSourcesAndOnlyInspectOnce() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		BankEquipmentRecommendationService service = new BankEquipmentRecommendationService((itemId, itemName, ttlDays) ->
		{
			calls.incrementAndGet();
			return CompletableFuture.completedFuture(item(itemId, itemName, 25));
		});

		EquipmentRecommendation recommendation = service.recommend(stabNpc(), Arrays.asList(
			new BankEquipmentRecommendationService.BankItemCandidate(100, "Sword", true, false),
			new BankEquipmentRecommendationService.BankItemCandidate(100, "Sword", false, true)
		), 7).get(5, TimeUnit.SECONDS);

		assertEquals(1, calls.get());
		assertEquals(1, recommendation.getItems().size());
		assertTrue(recommendation.getItems().get(0).isInBank());
		assertTrue(recommendation.getItems().get(0).isEquipped());
		assertEquals(Integer.valueOf(1), recommendation.bankItemRanks().get(100));
	}

	@Test
	public void batchLookupAvoidsPerItemLookups() throws Exception
	{
		AtomicInteger itemLookupCalls = new AtomicInteger();
		Map<Integer, ItemInspectInfo> batchItems = new LinkedHashMap<>();
		batchItems.put(1, item(1, "Bronze sword", 10));
		batchItems.put(2, item(2, "Iron sword", 20));
		BankEquipmentRecommendationService service = new BankEquipmentRecommendationService(
			(itemId, itemName, ttlDays) ->
			{
				itemLookupCalls.incrementAndGet();
				return CompletableFuture.completedFuture(null);
			},
			itemIds -> CompletableFuture.completedFuture(batchItems));

		EquipmentRecommendation recommendation = service.recommend(stabNpc(), Arrays.asList(
			new BankEquipmentRecommendationService.BankItemCandidate(1, "Bronze sword", true, false),
			new BankEquipmentRecommendationService.BankItemCandidate(2, "Iron sword", true, false)
		), 7).get(5, TimeUnit.SECONDS);

		assertEquals(0, itemLookupCalls.get());
		assertEquals(2, recommendation.getItems().size());
		assertEquals(2, recommendation.getItems().get(0).getItemId());
		assertEquals(Integer.valueOf(1), recommendation.bankItemRanks().get(2));
	}

	@Test
	public void failedLookupDoesNotDiscardSuccessfulCandidates() throws Exception
	{
		BankEquipmentRecommendationService service = new BankEquipmentRecommendationService((itemId, itemName, ttlDays) ->
		{
			if (itemId == 1)
			{
				CompletableFuture<ItemInspectInfo> failed = new CompletableFuture<>();
				failed.completeExceptionally(new IOException("offline"));
				return failed;
			}
			return CompletableFuture.completedFuture(item(itemId, itemName, 20));
		});

		EquipmentRecommendation recommendation = service.recommend(stabNpc(), Arrays.asList(
			new BankEquipmentRecommendationService.BankItemCandidate(1, "Unavailable", true, false),
			new BankEquipmentRecommendationService.BankItemCandidate(2, "Available", true, false)
		), 7).get(5, TimeUnit.SECONDS);

		assertEquals(1, recommendation.getItems().size());
		assertEquals(2, recommendation.getItems().get(0).getItemId());
	}

	@Test
	public void startsNextLookupOnlyAfterPreviousLookupCompletes() throws Exception
	{
		List<Integer> started = new ArrayList<>();
		CompletableFuture<ItemInspectInfo> firstLookup = new CompletableFuture<>();
		CompletableFuture<ItemInspectInfo> secondLookup = new CompletableFuture<>();
		BankEquipmentRecommendationService service = new BankEquipmentRecommendationService((itemId, itemName, ttlDays) ->
		{
			started.add(itemId);
			return itemId == 1 ? firstLookup : secondLookup;
		});

		CompletableFuture<EquipmentRecommendation> recommendation = service.recommend(stabNpc(), Arrays.asList(
			new BankEquipmentRecommendationService.BankItemCandidate(1, "First", true, false),
			new BankEquipmentRecommendationService.BankItemCandidate(2, "Second", true, false)
		), 7);

		assertEquals(Collections.singletonList(1), started);
		assertFalse(recommendation.isDone());

		firstLookup.complete(item(1, "First", 10));

		assertEquals(Arrays.asList(1, 2), started);
		assertFalse(recommendation.isDone());

		secondLookup.complete(item(2, "Second", 20));

		assertEquals(2, recommendation.get(5, TimeUnit.SECONDS).getItems().get(0).getItemId());
	}

	@Test
	public void recommendationIsCappedAtTwelveWithConsecutiveRanks() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		BankEquipmentRecommendationService service = new BankEquipmentRecommendationService((itemId, itemName, ttlDays) ->
		{
			calls.incrementAndGet();
			return CompletableFuture.completedFuture(item(itemId, itemName, itemId));
		});
		List<BankEquipmentRecommendationService.BankItemCandidate> candidates = new ArrayList<>();
		for (int itemId = 1; itemId <= 15; itemId++)
		{
			candidates.add(new BankEquipmentRecommendationService.BankItemCandidate(itemId, "Item " + itemId, true, false));
		}

		EquipmentRecommendation recommendation = service.recommend(stabNpc(), candidates, 7).get(5, TimeUnit.SECONDS);

		assertEquals(15, calls.get());
		assertEquals(12, recommendation.getItems().size());
		assertEquals(15, recommendation.getItems().get(0).getItemId());
		assertEquals(4, recommendation.getItems().get(11).getItemId());
		for (int index = 0; index < recommendation.getItems().size(); index++)
		{
			assertEquals(index + 1, recommendation.getItems().get(index).getRank());
		}
	}

	private static NpcCombatInfo stabNpc()
	{
		return NpcCombatInfo.builder()
			.stabDefence("1")
			.slashDefence("20")
			.crushDefence("30")
			.magicDefence("40")
			.lightRangedDefence("50")
			.standardRangedDefence("60")
			.heavyRangedDefence("70")
			.build();
	}

	private static ItemInspectInfo item(int itemId, String name, int attackStab)
	{
		return ItemInspectInfo.builder()
			.itemId(itemId)
			.displayName(name)
			.slot("Weapon")
			.attackStab(Integer.toString(attackStab))
			.build();
	}
}

package com.inspect.npc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.inspect.item.ItemInspectInfo;
import org.junit.Test;

public class CombatStyleRecommendationTest
{
	@Test
	public void selectsEachCombatStyleFromTheLowestDefence()
	{
		assertEquals(CombatStyleRecommendation.STAB, CombatStyleRecommendation.forNpc(npc("-5", "20", "30", "40", "50", "60", "70")));
		assertEquals(CombatStyleRecommendation.SLASH, CombatStyleRecommendation.forNpc(npc("20", "-5", "30", "40", "50", "60", "70")));
		assertEquals(CombatStyleRecommendation.CRUSH, CombatStyleRecommendation.forNpc(npc("20", "30", "-5", "40", "50", "60", "70")));
		assertEquals(CombatStyleRecommendation.MAGIC, CombatStyleRecommendation.forNpc(npc("20", "30", "40", "-5", "50", "60", "70")));
		assertEquals(CombatStyleRecommendation.RANGED, CombatStyleRecommendation.forNpc(npc("20", "30", "40", "50", "60", "-5", "70")));
	}

	@Test
	public void usesStableStyleOrderWhenDefencesTie()
	{
		NpcCombatInfo npc = npc("10", "10", "10", "10", "10", "10", "10");

		assertEquals(CombatStyleRecommendation.STAB, CombatStyleRecommendation.forNpc(npc));
	}

	@Test
	public void returnsNullWhenNoDefenceIsNumeric()
	{
		NpcCombatInfo npc = npc(null, "Unknown", "--", "N/A", "", null, "immune");

		assertNull(CombatStyleRecommendation.forNpc(npc));
		assertNull(CombatStyleRecommendation.forNpc(null));
	}

	@Test
	public void parsesFormattedNumbersAndRejectsMalformedValues()
	{
		assertEquals(-1234.5d, CombatStyleRecommendation.numericValue("Defence: -1,234.5%"), 0.0d);
		assertEquals(12.0d, CombatStyleRecommendation.numericValue("+12 bonus"), 0.0d);
		assertNull(CombatStyleRecommendation.numericValue("not available"));
		assertNull(CombatStyleRecommendation.numericValue("-"));
	}

	@Test
	public void scoreWeightsDamageAndPrayerAndUsesStyleSpecificBonuses()
	{
		ItemInspectInfo stabItem = ItemInspectInfo.builder()
			.attackStab("10")
			.strength("4")
			.prayer("20")
			.build();
		ItemInspectInfo rangedItem = ItemInspectInfo.builder()
			.attackRanged("10")
			.rangedStrength("4")
			.build();
		ItemInspectInfo nonPositiveItem = ItemInspectInfo.builder()
			.attackStab("-2")
			.build();

		assertEquals(18.0d, CombatStyleRecommendation.STAB.score(stabItem), 0.0d);
		assertTrue(CombatStyleRecommendation.STAB.isRelevant(stabItem));
		assertFalse(CombatStyleRecommendation.STAB.isRelevant(rangedItem));
		assertTrue(CombatStyleRecommendation.RANGED.isRelevant(rangedItem));
		assertFalse(CombatStyleRecommendation.STAB.isRelevant(nonPositiveItem));
	}

	private static NpcCombatInfo npc(
		String stab,
		String slash,
		String crush,
		String magic,
		String lightRanged,
		String standardRanged,
		String heavyRanged)
	{
		return NpcCombatInfo.builder()
			.stabDefence(stab)
			.slashDefence(slash)
			.crushDefence(crush)
			.magicDefence(magic)
			.lightRangedDefence(lightRanged)
			.standardRangedDefence(standardRanged)
			.heavyRangedDefence(heavyRanged)
			.build();
	}
}

