		EquipmentRecommendation recommendation = EquipmentRecommendation.fromBank(npc, Arrays.asList(
			item(1, "Accuracy weapon", "Weapon", "20", "0"),
			item(2, "Strength weapon", "Weapon", "1", "14"),
			item(3, "Balanced weapon", "Weapon", "12", "4"),
