	private static String wikiPageUrl(String query)
	{
		String page = query == null ? "" : query
			.replace('\u00A0', ' ')
			.trim()
			.replaceAll("\\s+", "_");
		if (page.isEmpty())
		{
			page = "Special:Search";
		}
		String encodedPage = URLEncoder.encode(page, StandardCharsets.UTF_8)
			.replace("+", "_")
			.replace("%3A", ":");
		return "https://oldschool.runescape.wiki/w/" + encodedPage;
	}

