		return "<html><body>"
			+ escape(item.getItemName())
			+ "<br>You: " + escape(comparison.getLocalItemName())
			+ "<br>Atk " + comparison.getAttackDelta()
			+ " | Def " + comparison.getDefenceDelta()
			+ " | Dmg " + comparison.getStrengthDelta()
