		return ironman;
	}

	public static ItemSourceAccountMode fromVarbitValue(int value)
	{
		switch (value)
		{
			case 1:
				return IRONMAN;
			case 2:
				return ULTIMATE_IRONMAN;
			case 3:
				return HARDCORE_IRONMAN;
			case 4:
				return GROUP_IRONMAN;
			case 5:
				return HARDCORE_GROUP_IRONMAN;
			case 6:
				return UNRANKED_GROUP_IRONMAN;
			default:
				return value > 0 ? IRONMAN : STANDARD;
		}
	}
}

package com.inspect.item;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
@Singleton
public class ItemInspectService
{
	private static final HttpUrl DEFAULT_WIKI_BASE = HttpUrl.get("https://oldschool.runescape.wiki");
	private static final String USER_AGENT = "Inspect RuneLite plugin (https://github.com/DevOldSchool/inspect)";
	private static final int EQUIPMENT_STATS_BATCH_SIZE = 50;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final HttpUrl wikiBase;
	private final ItemInspectParser parser = new ItemInspectParser();
	private final ItemInspectCache cache;

	@Inject
	ItemInspectService(OkHttpClient httpClient, Gson gson)
	{
		this(httpClient, gson, DEFAULT_WIKI_BASE,
			RuneLite.RUNELITE_DIR.toPath().resolve("inspect").resolve("item-inspect"));
	}

	ItemInspectService(OkHttpClient httpClient, Gson gson, HttpUrl wikiBase, Path cacheDirectory)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.wikiBase = wikiBase;
		this.cache = new ItemInspectCache(gson, cacheDirectory);
	}

	public void startUp(boolean clearCache)
	{
		cache.startUp(clearCache);
	}

	public void shutDown()
	{
		cache.shutDown();
	}

	public CompletableFuture<Void> clearCacheAsync()
	{
		return cache.clearAsync();
	}

	public CompletableFuture<ItemInspectInfo> inspect(int itemId, String itemName, int ttlDays)
	{
		if (itemId < 0 || itemName == null || itemName.trim().isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}

		long now = System.currentTimeMillis() / 1000L;
		return cache.get(itemId, now, ttlDays)
			.thenCompose(cached -> cached.map(CompletableFuture::completedFuture).orElseGet(() -> fetch(itemId, itemName)));
	}

	public CompletableFuture<ItemInspectInfo> inspect(ItemInspectVariant variant, int ttlDays)
	{
		if (variant == null || variant.getId() < 0 || variant.getWikiPage() == null
			|| variant.getWikiPage().trim().isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}

		long now = System.currentTimeMillis() / 1000L;
		return cache.get(variant.getId(), now, ttlDays)
			.thenCompose(cached -> cached.map(CompletableFuture::completedFuture).orElseGet(() -> fetch(variant)));
	}

	public CompletableFuture<List<ItemInspectVariant>> searchVariants(String query)
	{
		return searchVariants(query, 0);
	}

	public CompletableFuture<List<ItemInspectVariant>> searchVariants(String query, int ttlDays)
	{
		if (query == null || query.trim().isEmpty())
		{
			return CompletableFuture.completedFuture(Collections.emptyList());
		}

		String normalizedQuery = query.trim();
		long now = System.currentTimeMillis() / 1000L;
		return cache.getVariants(normalizedQuery, now, ttlDays)
			.thenCompose(cached -> cached
				.map(CompletableFuture::completedFuture)
				.orElseGet(() -> searchVariantsWiki(normalizedQuery)));
	}

	private CompletableFuture<List<ItemInspectVariant>> searchVariantsWiki(String query)
	{
		return searchPage(query)
			.thenCompose(page -> page == null
				? CompletableFuture.completedFuture(Collections.emptyList())
				: findVariants(page))
			.thenCompose(variants -> cache.putVariants(
				query,
				variants,
				System.currentTimeMillis() / 1000L).thenApply(ignored -> variants));
	}

	public CompletableFuture<ItemInspectInfo> search(String query)
	{
		return search(query, 0);
	}

	public CompletableFuture<ItemInspectInfo> search(String query, int ttlDays)
	{
		if (query == null || query.trim().isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}

		String normalizedQuery = query.trim();
		long now = System.currentTimeMillis() / 1000L;
		return cache.getBySearchTerm(normalizedQuery, now, ttlDays)
			.thenCompose(cached -> cached.map(CompletableFuture::completedFuture).orElseGet(() -> searchWiki(normalizedQuery)));
	}

	private CompletableFuture<ItemInspectInfo> searchWiki(String query)
	{
		return searchPage(query)
			.thenCompose(page ->
			{
				if (page == null)
				{
					return CompletableFuture.completedFuture(null);
				}

				ItemWikiLookup lookup = new ItemWikiLookup(page, null, wikiBase.newBuilder()
					.addPathSegment("w")
					.addPathSegment(page)
					.build()
					.toString());

				return fetchWikiPage(lookup)
					.thenApply(wikiPage -> parser.parse(-1, query, lookup, wikiPage.wikitext, wikiPage.categories))
					.thenCompose(info ->
					{
						if (info == null)
						{
							return CompletableFuture.completedFuture(null);
						}

						if (info.getItemId() < 0)
						{
							return CompletableFuture.completedFuture(info);
						}

						return cache.put(info).thenApply(ignored -> info);
					});
				});
	}

	public CompletableFuture<Map<Integer, ItemInspectInfo>> inspectEquipmentStats(Collection<Integer> itemIds)
	{
		if (itemIds == null || itemIds.isEmpty())
		{
			return CompletableFuture.completedFuture(Collections.emptyMap());
		}

		List<Integer> uniqueItemIds = new ArrayList<>(new LinkedHashSet<>(itemIds));
		Map<Integer, ItemInspectInfo> items = new LinkedHashMap<>();
		CompletableFuture<Void> lookupChain = CompletableFuture.completedFuture(null);
		for (int start = 0; start < uniqueItemIds.size(); start += EQUIPMENT_STATS_BATCH_SIZE)
		{
			List<Integer> batch = uniqueItemIds.subList(start, Math.min(start + EQUIPMENT_STATS_BATCH_SIZE, uniqueItemIds.size()));
			lookupChain = lookupChain.thenCompose(ignored -> fetchEquipmentStatsBatch(batch)
				.thenAccept(items::putAll));
		}
		return lookupChain.thenApply(ignored -> items);
	}

	private CompletableFuture<ItemInspectInfo> fetch(int itemId, String itemName)
	{
		return resolveLookup(itemId, itemName)
			.thenCompose(lookup -> fetchResolved(itemId, itemName, lookup));
	}

	private CompletableFuture<ItemInspectInfo> fetch(ItemInspectVariant variant)
	{
		ItemWikiLookup lookup = new ItemWikiLookup(
			variant.getWikiPage(),
			variant.getWikiAnchor(),
			variant.getSourceUrl());
		return fetchResolved(variant.getId(), variant.getDisplayName(), lookup);
	}

	private CompletableFuture<ItemInspectInfo> fetchResolved(int itemId, String itemName, ItemWikiLookup lookup)
	{
		if (lookup == null)
		{
			return CompletableFuture.completedFuture(null);
		}

		return fetchWikiPage(lookup)
			.thenApply(wikiPage -> parser.parse(itemId, itemName, lookup, wikiPage.wikitext, wikiPage.categories))
			.thenCompose(info ->
			{
				if (info == null)
				{
					return CompletableFuture.completedFuture(null);
				}
				return cache.put(info).thenApply(ignored -> info);
			});
	}

	private CompletableFuture<String> searchPage(String query)
	{
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("list", "search")
			.addQueryParameter("srnamespace", "0")
			.addQueryParameter("srlimit", "1")
			.addQueryParameter("srsearch", query)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki search response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				JsonArray search = json.getAsJsonObject("query").getAsJsonArray("search");
				if (search == null || search.size() == 0)
				{
					return null;
				}
				return search.get(0).getAsJsonObject().get("title").getAsString();
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki search response", ex);
			}
		});
	}

	private CompletableFuture<ItemWikiLookup> resolveLookup(int itemId, String itemName)
	{
		String query = "bucket('infobox_item').select('item_name','version_anchor').where('item_id','"
			+ itemId
			+ "').limit(1).run()";
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki bucket response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				JsonArray bucket = json.getAsJsonArray("bucket");
				if (bucket == null || bucket.size() == 0)
				{
					log.debug("Wiki item bucket lookup for {} ({}) did not return a row", itemName, itemId);
					return null;
				}

				JsonObject row = bucket.get(0).getAsJsonObject();
				String page = normalizedPageTitle(firstString(row, "item_name"));
				if (page == null)
				{
					return null;
				}

				String anchor = normalizedAnchor(firstString(row, "version_anchor"));
				return new ItemWikiLookup(page, anchor, wikiUrl(page, anchor));
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki bucket response", ex);
			}
		});
	}

	private CompletableFuture<List<ItemInspectVariant>> findVariants(String page)
	{
		String query = "bucket('infobox_item')"
			+ ".select('page_name','item_id','item_name','version_anchor')"
			+ ".where('page_name','"
			+ bucketLiteral(page)
			+ "').limit(50).run()";
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki item variant response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				JsonArray bucket = json.getAsJsonArray("bucket");
				if (bucket == null || bucket.size() == 0)
				{
					return Collections.emptyList();
				}

				Map<Integer, ItemInspectVariant> variants = new LinkedHashMap<>();
				for (JsonElement element : bucket)
				{
					JsonObject row = element.getAsJsonObject();
					int itemId = firstNumericId(row, "item_id");
					if (itemId < 0)
					{
						continue;
					}

					String variantPage = normalizedPageTitle(firstString(row, "page_name"));
					if (variantPage == null)
					{
						variantPage = normalizedPageTitle(page);
					}
					String anchor = normalizedAnchor(firstString(row, "version_anchor"));
					String displayName = firstString(row, "item_name");
					if (displayName == null || displayName.trim().isEmpty())
					{
						displayName = page;
					}
					variants.putIfAbsent(itemId, new ItemInspectVariant(
						itemId,
						displayName,
						variantPage,
						anchor,
						wikiUrl(variantPage, anchor)));
				}

				List<ItemInspectVariant> sorted = new ArrayList<>(variants.values());
				sorted.sort(Comparator
					.comparing(ItemInspectVariant::getDisplayName, Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER))
					.thenComparing(ItemInspectVariant::getWikiAnchor, Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER))
					.thenComparingInt(ItemInspectVariant::getId));
				return Collections.unmodifiableList(sorted);
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki item variant response", ex);
			}
		});
	}

	private CompletableFuture<Map<Integer, ItemInspectInfo>> fetchEquipmentStatsBatch(Collection<Integer> itemIds)
	{
		String query = "bucket('infobox_item')"
			+ ".join('infobox_bonuses','infobox_bonuses.page_name','page_name')"
			+ ".select('page_name','page_name_sub','item_id','item_name',"
			+ "'infobox_bonuses.page_name_sub','infobox_bonuses.equipment_slot',"
			+ "'infobox_bonuses.stab_attack_bonus','infobox_bonuses.slash_attack_bonus','infobox_bonuses.crush_attack_bonus',"
			+ "'infobox_bonuses.magic_attack_bonus','infobox_bonuses.range_attack_bonus',"
			+ "'infobox_bonuses.stab_defence_bonus','infobox_bonuses.slash_defence_bonus','infobox_bonuses.crush_defence_bonus',"
			+ "'infobox_bonuses.magic_defence_bonus','infobox_bonuses.range_defence_bonus',"
			+ "'infobox_bonuses.strength_bonus','infobox_bonuses.ranged_strength_bonus','infobox_bonuses.magic_damage_bonus',"
			+ "'infobox_bonuses.prayer_bonus','infobox_bonuses.weapon_attack_speed','infobox_bonuses.weapon_attack_range')"
			+ ".where("
			+ bucketOrConditions("item_id", itemIds)
			+ ").limit(5000).run()";
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		Set<Integer> requestedItemIds = new LinkedHashSet<>(itemIds);
		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki equipment bucket response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				JsonArray bucket = json.getAsJsonArray("bucket");
				if (bucket == null || bucket.size() == 0)
				{
					return Collections.emptyMap();
				}

				Map<Integer, ItemInspectInfo> items = new LinkedHashMap<>();
				for (JsonElement element : bucket)
				{
					JsonObject row = element.getAsJsonObject();
					String itemSubpage = firstString(row, "page_name_sub");
					String bonusSubpage = firstString(row, "infobox_bonuses.page_name_sub");
					if (itemSubpage != null && bonusSubpage != null && !itemSubpage.equals(bonusSubpage))
					{
						continue;
					}

					for (int itemId : requestedItemIds(row, requestedItemIds))
					{
						items.put(itemId, equipmentInfo(row, itemId));
					}
				}
				return items;
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki equipment bucket response", ex);
			}
		});
	}

	private CompletableFuture<WikiPage> fetchWikiPage(ItemWikiLookup lookup)
	{
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "parse")
			.addQueryParameter("format", "json")
			.addQueryParameter("page", lookup.getPage())
			.addQueryParameter("prop", "wikitext|categories")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				JsonObject parse = json.getAsJsonObject("parse");
				String wikitext = parse.getAsJsonObject("wikitext").get("*").getAsString();
				List<String> categories = new ArrayList<>();
				JsonArray categoryEntries = parse.getAsJsonArray("categories");
				if (categoryEntries != null)
				{
					for (JsonElement categoryEntry : categoryEntries)
					{
						JsonElement category = categoryEntry.getAsJsonObject().get("*");
						if (category != null && !category.isJsonNull())
						{
							categories.add(category.getAsString());
						}
					}
				}
				return new WikiPage(wikitext, categories);
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki response", ex);
			}
		});
	}

	private static CompletableFuture<Response> execute(OkHttpClient client, Request request)
	{
		CompletableFuture<Response> future = new CompletableFuture<>();
		client.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				if (!response.isSuccessful() && response.code() / 100 != 3)
				{
					try (Response closeable = response)
					{
						future.completeExceptionally(new IOException("Unexpected wiki response: " + closeable.code()));
					}
					return;
				}

				future.complete(response);
			}
		});
		return future;
	}

	private static String bucketOrConditions(String field, Collection<Integer> itemIds)
	{
		StringBuilder query = new StringBuilder("bucket.Or(");
		boolean first = true;
		for (int itemId : itemIds)
		{
			if (!first)
			{
				query.append(',');
			}
			query.append("{'")
				.append(field)
				.append("','")
				.append(itemId)
				.append("'}");
			first = false;
		}
		return query.append(')').toString();
	}

	private static String bucketLiteral(String value)
	{
		return value.replace("\\", "\\\\").replace("'", "\\'");
	}

	private static int firstNumericId(JsonObject row, String key)
	{
		JsonElement element = row.get(key);
		if (element == null || element.isJsonNull())
		{
			return -1;
		}

		if (element.isJsonArray())
		{
			for (JsonElement candidate : element.getAsJsonArray())
			{
				int id = numericId(candidate);
				if (id >= 0)
				{
					return id;
				}
			}
			return -1;
		}

		return numericId(element);
	}

	private static int numericId(JsonElement element)
	{
		if (element == null || element.isJsonNull())
		{
			return -1;
		}

		String value = element.getAsString();
		if (!value.matches("\\d+"))
		{
			return -1;
		}

		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException ignored)
		{
			return -1;
		}
	}

	private static Set<Integer> requestedItemIds(JsonObject row, Set<Integer> requestedItemIds)
	{
		Set<Integer> itemIds = new LinkedHashSet<>();
		JsonElement itemIdElement = row.get("item_id");
		if (itemIdElement == null || itemIdElement.isJsonNull())
		{
			return itemIds;
		}

		if (itemIdElement.isJsonArray())
		{
			for (JsonElement element : itemIdElement.getAsJsonArray())
			{
				addRequestedItemId(itemIds, requestedItemIds, element);
			}
			return itemIds;
		}

		addRequestedItemId(itemIds, requestedItemIds, itemIdElement);
		return itemIds;
	}

	private static void addRequestedItemId(Set<Integer> itemIds, Set<Integer> requestedItemIds, JsonElement element)
	{
		try
		{
			int itemId = Integer.parseInt(element.getAsString());
			if (requestedItemIds.contains(itemId))
			{
				itemIds.add(itemId);
			}
		}
		catch (NumberFormatException ignored)
		{
			// Ignore malformed wiki bucket rows.
		}
	}

	private ItemInspectInfo equipmentInfo(JsonObject row, int itemId)
	{
		String page = normalizedPageTitle(firstString(row, "page_name"));
		String anchor = normalizedAnchor(firstString(row, "page_name_sub"));
		return ItemInspectInfo.builder()
			.itemId(itemId)
			.wikiPage(page)
			.wikiAnchor(anchor)
			.displayName(firstString(row, "item_name"))
			.attackStab(stringValue(row, "infobox_bonuses.stab_attack_bonus"))
			.attackSlash(stringValue(row, "infobox_bonuses.slash_attack_bonus"))
			.attackCrush(stringValue(row, "infobox_bonuses.crush_attack_bonus"))
			.attackMagic(stringValue(row, "infobox_bonuses.magic_attack_bonus"))
			.attackRanged(stringValue(row, "infobox_bonuses.range_attack_bonus"))
			.defenceStab(stringValue(row, "infobox_bonuses.stab_defence_bonus"))
			.defenceSlash(stringValue(row, "infobox_bonuses.slash_defence_bonus"))
			.defenceCrush(stringValue(row, "infobox_bonuses.crush_defence_bonus"))
			.defenceMagic(stringValue(row, "infobox_bonuses.magic_defence_bonus"))
			.defenceRanged(stringValue(row, "infobox_bonuses.range_defence_bonus"))
			.strength(stringValue(row, "infobox_bonuses.strength_bonus"))
			.rangedStrength(stringValue(row, "infobox_bonuses.ranged_strength_bonus"))
			.magicDamage(stringValue(row, "infobox_bonuses.magic_damage_bonus"))
			.prayer(stringValue(row, "infobox_bonuses.prayer_bonus"))
			.slot(firstString(row, "infobox_bonuses.equipment_slot"))
			.attackSpeed(stringValue(row, "infobox_bonuses.weapon_attack_speed"))
			.attackRange(stringValue(row, "infobox_bonuses.weapon_attack_range"))
			.fetchedAtEpochSecond(Instant.now().getEpochSecond())
			.sourceUrl(page == null ? null : wikiUrl(page, anchor))
			.build();
	}

	private static String firstString(JsonObject json, String key)
	{
		JsonElement element = json.get(key);
		if (element == null || element.isJsonNull())
		{
			return null;
		}

		if (element.isJsonArray())
		{
			JsonArray array = element.getAsJsonArray();
			if (array.size() == 0 || array.get(0).isJsonNull())
			{
				return null;
			}
			return array.get(0).getAsString();
		}

		return element.getAsString();
	}

	private static String stringValue(JsonObject json, String key)
	{
		JsonElement element = json.get(key);
		if (element == null || element.isJsonNull())
		{
			return null;
		}
		return element.getAsString();
	}

	private String wikiUrl(String page, String anchor)
	{
		HttpUrl.Builder builder = wikiBase.newBuilder()
			.addPathSegment("w")
			.addPathSegment(page);
		if (anchor != null)
		{
			builder.fragment(anchor);
		}
		return builder.build().toString();
	}

	private static String normalizedPageTitle(String page)
	{
		if (page == null || page.trim().isEmpty())
		{
			return null;
		}
		return page.trim().replace(' ', '_');
	}

	private static String normalizedAnchor(String anchor)
	{
		if (anchor == null || anchor.trim().isEmpty())
		{
			return null;
		}
		return anchor.trim().replace(' ', '_');
	}

	private static final class WikiPage
	{
		private final String wikitext;
		private final List<String> categories;

		private WikiPage(String wikitext, List<String> categories)
		{
			this.wikitext = wikitext;
			this.categories = categories;
		}
	}
}

package com.inspect.npc;

import com.inspect.item.ItemInspectInfo;
import lombok.Getter;

import java.util.Comparator;
import java.util.Locale;
import java.util.Objects;

public enum CombatStyleRecommendation
{
	STAB("Stab melee", "Stab defence")
		{
			@Override
			double score(ItemInspectInfo item)
			{
				return offensiveScore(item.getAttackStab(), item.getStrength(), item.getPrayer());
			}
		},
	SLASH("Slash melee", "Slash defence")
		{
			@Override
			double score(ItemInspectInfo item)
			{
				return offensiveScore(item.getAttackSlash(), item.getStrength(), item.getPrayer());
			}
		},
	CRUSH("Crush melee", "Crush defence")
		{
			@Override
			double score(ItemInspectInfo item)
			{
				return offensiveScore(item.getAttackCrush(), item.getStrength(), item.getPrayer());
			}
		},
	MAGIC("Magic", "Magic defence")
		{
			@Override
			double score(ItemInspectInfo item)
			{
				return offensiveScore(item.getAttackMagic(), item.getMagicDamage(), item.getPrayer());
			}
		},
	RANGED("Ranged", "Ranged defence")
		{
			@Override
			double score(ItemInspectInfo item)
			{
				return offensiveScore(item.getAttackRanged(), item.getRangedStrength(), item.getPrayer());
			}
		};

	@Getter
    private final String displayName;
	private final String defenceLabel;

	CombatStyleRecommendation(String displayName, String defenceLabel)
	{
		this.displayName = displayName;
		this.defenceLabel = defenceLabel;
	}

    String getDefenceLabel()
	{
		return defenceLabel;
	}

	abstract double score(ItemInspectInfo item);

	boolean isRelevant(ItemInspectInfo item)
	{
		return score(item) > 0;
	}

	public static CombatStyleRecommendation forNpc(NpcCombatInfo info)
	{
		if (info == null)
		{
			return null;
		}

		return java.util.stream.Stream.of(
				candidate(STAB, info.getStabDefence()),
				candidate(SLASH, info.getSlashDefence()),
				candidate(CRUSH, info.getCrushDefence()),
				candidate(MAGIC, info.getMagicDefence()),
				candidate(RANGED, lowest(info.getLightRangedDefence(), info.getStandardRangedDefence(), info.getHeavyRangedDefence()))
			)
			.filter(Objects::nonNull)
			.min(Comparator.comparingDouble(candidate -> candidate.defence))
			.map(candidate -> candidate.style)
			.orElse(null);
	}

	static Double numericValue(String value)
	{
		if (value == null || value.isEmpty())
		{
			return null;
		}

		String normalized = value.replace(",", "").toLowerCase(Locale.ENGLISH);
		StringBuilder number = new StringBuilder();
		boolean started = false;
		boolean hasDecimal = false;
		for (int i = 0; i < normalized.length(); i++)
		{
			char c = normalized.charAt(i);
			if (!started && (c == '+' || c == '-' || Character.isDigit(c)))
			{
				number.append(c);
				started = true;
				continue;
			}

			if (started && Character.isDigit(c))
			{
				number.append(c);
				continue;
			}

			if (started && c == '.' && !hasDecimal)
			{
				number.append(c);
				hasDecimal = true;
				continue;
			}

			if (started)
			{
				break;
			}
		}

		if (number.length() == 0 || "+".contentEquals(number) || "-".contentEquals(number))
		{
			return null;
		}

		try
		{
			return Double.parseDouble(number.toString());
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private static Candidate candidate(CombatStyleRecommendation style, String defence)
	{
		Double value = numericValue(defence);
		return value == null ? null : new Candidate(style, value);
	}

	private static String lowest(String... values)
	{
		Double lowest = null;
		for (String value : values)
		{
			Double numeric = numericValue(value);
			if (numeric != null && (lowest == null || numeric < lowest))
			{
				lowest = numeric;
			}
		}
		return lowest == null ? null : Double.toString(lowest);
	}

	private static double offensiveScore(String accuracy, String damage, String prayer)
	{
		return value(accuracy) + value(damage) * 1.5d + value(prayer) * 0.1d;
	}

	private static double value(String value)
	{
		Double numeric = numericValue(value);
		return numeric == null ? 0 : numeric;
	}

	private static final class Candidate
	{
		private final CombatStyleRecommendation style;
		private final double defence;

		private Candidate(CombatStyleRecommendation style, double defence)
		{
			this.style = style;
			this.defence = defence;
		}
	}
}

package com.inspect.npc;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.file.Path;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
@Singleton
public class NpcInspectService
{
	private static final HttpUrl DEFAULT_WIKI_BASE = HttpUrl.get("https://oldschool.runescape.wiki");
	private static final String USER_AGENT = "Inspect RuneLite plugin (https://github.com/DevOldSchool/inspect)";

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final HttpUrl wikiBase;
	private final NpcInspectParser parser = new NpcInspectParser();
	private final NpcInspectCache cache;

	@Inject
	NpcInspectService(OkHttpClient httpClient, Gson gson)
	{
		this(httpClient, gson, DEFAULT_WIKI_BASE,
			RuneLite.RUNELITE_DIR.toPath().resolve("inspect").resolve("npc-inspect"));
	}

	NpcInspectService(OkHttpClient httpClient, Gson gson, HttpUrl wikiBase, Path cacheDirectory)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.wikiBase = wikiBase;
		this.cache = new NpcInspectCache(gson, cacheDirectory);
	}

	public void startUp(boolean clearCache)
	{
		cache.startUp(clearCache);
	}

	public void shutDown()
	{
		cache.shutDown();
	}

	public CompletableFuture<Void> clearCacheAsync()
	{
		return cache.clearAsync();
	}

	public CompletableFuture<NpcCombatInfo> inspect(NPC npc, int ttlDays)
	{
		if (npc == null)
		{
			return CompletableFuture.completedFuture(null);
		}

		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null || composition.getName() == null)
		{
			return CompletableFuture.completedFuture(null);
		}

		return inspect(composition.getId(), composition.getName(), ttlDays);
	}

	public CompletableFuture<NpcCombatInfo> inspect(int npcId, String npcName, int ttlDays)
	{
		if (npcId < 0 || npcName == null || npcName.trim().isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}

		long now = System.currentTimeMillis() / 1000L;
		return cache.get(npcId, now, ttlDays)
			.thenCompose(cached -> cached.map(CompletableFuture::completedFuture).orElseGet(() -> fetch(npcId, npcName)));
	}

	public CompletableFuture<NpcCombatInfo> search(String query)
	{
		return search(query, 7);
	}

	public CompletableFuture<NpcCombatInfo> search(String query, int ttlDays)
	{
		if (query == null || query.trim().isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}

		String normalizedQuery = query.trim();
		long now = System.currentTimeMillis() / 1000L;
		return cache.getBySearchTerm(normalizedQuery, now, ttlDays)
			.thenCompose(cached -> cached.map(CompletableFuture::completedFuture).orElseGet(() -> searchWiki(normalizedQuery)));
	}

	private CompletableFuture<NpcCombatInfo> searchWiki(String query)
	{
		return searchPage(query)
			.thenCompose(page ->
			{
				if (page == null)
				{
					return CompletableFuture.completedFuture(null);
				}

				NpcWikiLookup lookup = new NpcWikiLookup(page, null, wikiBase.newBuilder()
					.addPathSegment("w")
					.addPathSegment(page)
					.build()
					.toString());

				return fetchWikitext(lookup)
					.thenApply(wikitext -> parser.parse(-1, query.trim(), lookup, wikitext))
					.thenCompose(info ->
					{
						if (info == null)
						{
							return CompletableFuture.completedFuture(null);
						}

						if (info.getNpcId() < 0)
						{
							return CompletableFuture.completedFuture(info);
						}

						return cache.put(info).thenApply(ignored -> info);
					});
			});
	}

	private CompletableFuture<NpcCombatInfo> fetch(int npcId, String npcName)
	{
		return resolveLookup(npcId, npcName)
			.thenCompose(lookup ->
			{
				if (lookup == null)
				{
					return CompletableFuture.completedFuture(null);
				}
				return fetchWikitext(lookup)
					.thenApply(wikitext -> parser.parse(npcId, npcName, lookup, wikitext))
					.thenCompose(info ->
					{
						if (info == null)
						{
							return CompletableFuture.completedFuture(null);
						}
						return cache.put(info).thenApply(ignored -> info);
					});
			});
	}

	private CompletableFuture<String> searchPage(String query)
	{
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("list", "search")
			.addQueryParameter("srnamespace", "0")
			.addQueryParameter("srlimit", "1")
			.addQueryParameter("srsearch", query)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki search response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				JsonArray search = json.getAsJsonObject("query").getAsJsonArray("search");
				if (search == null || search.size() == 0)
				{
					return null;
				}
				return search.get(0).getAsJsonObject().get("title").getAsString();
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki search response", ex);
			}
		});
	}

	private CompletableFuture<NpcWikiLookup> resolveLookup(int npcId, String npcName)
	{
		String query = "bucket('infobox_monster').select('name','version_anchor').where('id','"
			+ npcId
			+ "').limit(1).run()";
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki bucket response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				JsonArray bucket = json.getAsJsonArray("bucket");
				if (bucket == null || bucket.size() == 0)
				{
					log.debug("Wiki NPC bucket lookup for {} ({}) did not return a row", npcName, npcId);
					return null;
				}

				JsonObject row = bucket.get(0).getAsJsonObject();
				String page = normalizedPageTitle(firstString(row, "name"));
				if (page == null)
				{
					return null;
				}

				String anchor = normalizedAnchor(firstString(row, "version_anchor"));
				return new NpcWikiLookup(page, anchor, wikiUrl(page, anchor));
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki bucket response", ex);
			}
		});
	}

	private CompletableFuture<String> fetchWikitext(NpcWikiLookup lookup)
	{
		HttpUrl url = wikiBase.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "parse")
			.addQueryParameter("format", "json")
			.addQueryParameter("page", lookup.getPage())
			.addQueryParameter("prop", "wikitext")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		return execute(httpClient, request).thenApply(response ->
		{
			try (Response closeable = response; ResponseBody body = closeable.body())
			{
				if (body == null)
				{
					throw new IllegalStateException("Wiki response did not include a body");
				}

				JsonObject json = gson.fromJson(body.string(), JsonObject.class);
				return json.getAsJsonObject("parse")
					.getAsJsonObject("wikitext")
					.get("*")
					.getAsString();
			}
			catch (IOException ex)
			{
				throw new IllegalStateException("Unable to read wiki response", ex);
			}
		});
	}

	private static CompletableFuture<Response> execute(OkHttpClient client, Request request)
	{
		CompletableFuture<Response> future = new CompletableFuture<>();
		client.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				if (!response.isSuccessful() && response.code() / 100 != 3)
				{
					try (Response closeable = response)
					{
						future.completeExceptionally(new IOException("Unexpected wiki response: " + closeable.code()));
					}
					return;
				}

				future.complete(response);
			}
		});
		return future;
	}

	private static String firstString(JsonObject json, String key)
	{
		JsonElement element = json.get(key);
		if (element == null || element.isJsonNull())
		{
			return null;
		}

		if (element.isJsonArray())
		{
			JsonArray array = element.getAsJsonArray();
			if (array.size() == 0 || array.get(0).isJsonNull())
			{
				return null;
			}
			return array.get(0).getAsString();
		}

		return element.getAsString();
	}

	private String wikiUrl(String page, String anchor)
	{
		HttpUrl.Builder builder = wikiBase.newBuilder()
			.addPathSegment("w")
			.addPathSegment(page);
		if (anchor != null)
		{
			builder.fragment(anchor);
		}
		return builder.build().toString();
	}

	private static String normalizedPageTitle(String page)
	{
		if (page == null || page.trim().isEmpty())
		{
			return null;
		}
		return page.trim().replace(' ', '_');
	}

	private static String normalizedAnchor(String anchor)
	{
		if (anchor == null || anchor.trim().isEmpty())
		{
			return null;
		}
		return anchor.trim().replace(' ', '_');
	}
}

package com.inspect.npc;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Value;

@Value
public class NpcItemRequirementStatus
{
	NpcItemRequirement requirement;
	List<NpcItemRequirementAlternativeStatus> alternatives;

	public NpcItemRequirementStatus(NpcItemRequirement requirement, List<NpcItemRequirementAlternativeStatus> alternatives)
	{
		this.requirement = requirement;
		this.alternatives = alternatives == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(alternatives));
	}

	public String label()
	{
		return requirement == null ? "Required item" : requirement.getLabel();
	}

	public boolean isMet()
	{
		for (NpcItemRequirementAlternativeStatus alternative : alternatives)
		{
			if (alternative.isMet())
			{
				return true;
			}
		}
		return false;
	}

	public String statusText()
	{
		if (isMet())
		{
			return "Met";
		}

		if (requirement == null || !requirement.hasAlternatives())
		{
			return "Missing";
		}

		return "Missing: " + String.join(" or ", requirement.getAlternatives());
	}
}

package com.inspect.npc;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;

@Slf4j
class NpcInspectCache
{
	private static final String INDEX_FILE = "index.json";

	private final Gson gson;
	private final Path cacheDirectory;
	private final ExecutorService executor = Executors.newSingleThreadExecutor(runnable ->
	{
		Thread thread = new Thread(runnable, "inspect-npc-cache");
		thread.setDaemon(true);
		return thread;
	});
	private final Map<Integer, NpcCombatInfo> memoryCache = new HashMap<>();
	private final Map<Integer, String> cacheKeysByNpc = new HashMap<>();

	NpcInspectCache(Gson gson, Path cacheDirectory)
	{
		this.gson = gson;
		this.cacheDirectory = cacheDirectory;
	}

	void startUp(boolean clearCache)
	{
		if (clearCache)
		{
			clearAsync();
		}
	}

	void shutDown()
	{
		memoryCache.clear();
		cacheKeysByNpc.clear();
		executor.shutdownNow();
	}

	CompletableFuture<Optional<NpcCombatInfo>> get(int npcId, long nowEpochSecond, int ttlDays)
	{
		synchronized (this)
		{
			NpcCombatInfo cached = memoryCache.get(npcId);
			if (cached != null)
			{
				if (!cached.isExpired(nowEpochSecond, ttlDays))
				{
					return CompletableFuture.completedFuture(Optional.of(cached));
				}
				memoryCache.remove(npcId);
			}
		}

		return CompletableFuture.supplyAsync(() -> readFromDisk(npcId, nowEpochSecond, ttlDays), executor);
	}

	CompletableFuture<Optional<NpcCombatInfo>> getBySearchTerm(String searchTerm, long nowEpochSecond, int ttlDays)
	{
		String normalizedSearchTerm = normalizeSearchTerm(searchTerm);
		if (normalizedSearchTerm.isEmpty())
		{
			return CompletableFuture.completedFuture(Optional.empty());
		}

		synchronized (this)
		{
			for (NpcCombatInfo cached : memoryCache.values())
			{
				if (!cached.isExpired(nowEpochSecond, ttlDays) && matchesSearchTerm(cached, normalizedSearchTerm))
				{
					return CompletableFuture.completedFuture(Optional.of(cached));
				}
			}
		}

		return CompletableFuture.supplyAsync(() -> readBySearchTerm(normalizedSearchTerm, nowEpochSecond, ttlDays), executor);
	}

	CompletableFuture<Void> put(NpcCombatInfo info)
	{
		synchronized (this)
		{
			memoryCache.put(info.getNpcId(), info);
			cacheKeysByNpc.put(info.getNpcId(), info.cacheKey());
		}

		return CompletableFuture.runAsync(() -> writeToDisk(info), executor);
	}

	CompletableFuture<Void> clearAsync()
	{
		synchronized (this)
		{
			memoryCache.clear();
			cacheKeysByNpc.clear();
		}

		return CompletableFuture.runAsync(() ->
		{
			if (!Files.isDirectory(cacheDirectory))
			{
				return;
			}

			try (Stream<Path> files = Files.list(cacheDirectory))
			{
				files.forEach(path ->
				{
					try
					{
						Files.deleteIfExists(path);
					}
					catch (IOException ex)
					{
						log.debug("Unable to delete NPC Inspect cache file {}", path, ex);
					}
				});
			}
			catch (IOException ex)
			{
				log.debug("Unable to clear NPC Inspect cache", ex);
			}
		}, executor);
	}

	private Optional<NpcCombatInfo> readFromDisk(int npcId, long nowEpochSecond, int ttlDays)
	{
		try
		{
			Files.createDirectories(cacheDirectory);
			loadIndexIfNeeded();

			String cacheKey;
			synchronized (this)
			{
				cacheKey = cacheKeysByNpc.get(npcId);
			}
			if (cacheKey == null)
			{
				return Optional.empty();
			}

			Path cacheFile = cachePath(cacheKey);
			if (!Files.isRegularFile(cacheFile))
			{
				return Optional.empty();
			}

			try (Reader reader = Files.newBufferedReader(cacheFile, StandardCharsets.UTF_8))
			{
				NpcCombatInfo info = gson.fromJson(reader, NpcCombatInfo.class);
				if (info == null
					|| info.getNpcId() != npcId
					|| !info.hasCurrentCacheSchema()
					|| !cacheKey.equals(info.cacheKey())
					|| info.isExpired(nowEpochSecond, ttlDays))
				{
					Files.deleteIfExists(cacheFile);
					removeIndex(npcId);
					return Optional.empty();
				}

				synchronized (this)
				{
					memoryCache.put(npcId, info);
					cacheKeysByNpc.put(npcId, cacheKey);
				}
				return Optional.of(info);
			}
			catch (RuntimeException | IOException ex)
			{
				log.debug("Ignoring corrupt NPC Inspect cache file {}", cacheFile, ex);
				Files.deleteIfExists(cacheFile);
				removeIndex(npcId);
				return Optional.empty();
			}
		}
		catch (IOException ex)
		{
			log.debug("Unable to read NPC Inspect cache", ex);
			return Optional.empty();
		}
	}

	private Optional<NpcCombatInfo> readBySearchTerm(String normalizedSearchTerm, long nowEpochSecond, int ttlDays)
	{
		try
		{
			Files.createDirectories(cacheDirectory);
			loadIndexIfNeeded();

			Map<Integer, String> cacheKeys;
			synchronized (this)
			{
				cacheKeys = new HashMap<>(cacheKeysByNpc);
			}

			for (Map.Entry<Integer, String> entry : cacheKeys.entrySet())
			{
				Optional<NpcCombatInfo> cached = readCachedInfo(entry.getKey(), entry.getValue(), nowEpochSecond, ttlDays);
				if (cached.isPresent() && matchesSearchTerm(cached.get(), normalizedSearchTerm))
				{
					return cached;
				}
			}
		}
		catch (IOException ex)
		{
			log.debug("Unable to read NPC Inspect cache by search term", ex);
		}
		return Optional.empty();
	}

	private Optional<NpcCombatInfo> readCachedInfo(int npcId, String cacheKey, long nowEpochSecond, int ttlDays)
		throws IOException
	{
		Path cacheFile = cachePath(cacheKey);
		if (!Files.isRegularFile(cacheFile))
		{
			return Optional.empty();
		}

		try (Reader reader = Files.newBufferedReader(cacheFile, StandardCharsets.UTF_8))
		{
			NpcCombatInfo info = gson.fromJson(reader, NpcCombatInfo.class);
			if (info == null
				|| info.getNpcId() != npcId
				|| !info.hasCurrentCacheSchema()
				|| !cacheKey.equals(info.cacheKey())
				|| info.isExpired(nowEpochSecond, ttlDays))
			{
				Files.deleteIfExists(cacheFile);
				removeIndex(npcId);
				return Optional.empty();
			}

			synchronized (this)
			{
				memoryCache.put(npcId, info);
				cacheKeysByNpc.put(npcId, cacheKey);
			}
			return Optional.of(info);
		}
		catch (RuntimeException | IOException ex)
		{
			log.debug("Ignoring corrupt NPC Inspect cache file {}", cacheFile, ex);
			Files.deleteIfExists(cacheFile);
			removeIndex(npcId);
			return Optional.empty();
		}
	}

	private void writeToDisk(NpcCombatInfo info)
	{
		try
		{
			Files.createDirectories(cacheDirectory);
			Path cacheFile = cachePath(info.cacheKey());
			Path tempFile = cacheDirectory.resolve(info.cacheKey() + ".tmp");

			try (Writer writer = Files.newBufferedWriter(tempFile, StandardCharsets.UTF_8))
			{
				gson.toJson(info, writer);
			}
			Files.move(tempFile, cacheFile, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			writeIndex();
		}
		catch (IOException ex)
		{
			log.debug("Unable to write NPC Inspect cache", ex);
		}
	}

	private void loadIndexIfNeeded() throws IOException
	{
		synchronized (this)
		{
			if (!cacheKeysByNpc.isEmpty())
			{
				return;
			}
		}

		Path indexFile = cacheDirectory.resolve(INDEX_FILE);
		if (!Files.isRegularFile(indexFile))
		{
			return;
		}

		try (Reader reader = Files.newBufferedReader(indexFile, StandardCharsets.UTF_8))
		{
			JsonObject index = gson.fromJson(reader, JsonObject.class);
			if (index == null)
			{
				return;
			}

			Map<Integer, String> loadedCacheKeys = new HashMap<>();
			for (Map.Entry<String, JsonElement> entry : index.entrySet())
			{
				int npcId = Integer.parseInt(entry.getKey());
				String cacheKey = entry.getValue().getAsString();
				if (npcId < 0 || !isValidCacheKey(cacheKey))
				{
					throw new IllegalArgumentException("Invalid NPC Inspect cache index entry");
				}
				loadedCacheKeys.put(npcId, cacheKey);
			}

			synchronized (this)
			{
				cacheKeysByNpc.putAll(loadedCacheKeys);
			}
		}
		catch (RuntimeException ex)
		{
			log.debug("Ignoring corrupt NPC Inspect cache index", ex);
			Files.deleteIfExists(indexFile);
		}
	}

	private void writeIndex() throws IOException
	{
		JsonObject index = new JsonObject();
		synchronized (this)
		{
			for (Map.Entry<Integer, String> entry : cacheKeysByNpc.entrySet())
			{
				index.addProperty(Integer.toString(entry.getKey()), entry.getValue());
			}
		}

		Path tempFile = cacheDirectory.resolve(INDEX_FILE + ".tmp");
		try (Writer writer = Files.newBufferedWriter(tempFile, StandardCharsets.UTF_8))
		{
			gson.toJson(index, writer);
		}
		Files.move(tempFile, cacheDirectory.resolve(INDEX_FILE), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
	}

	private void removeIndex(int npcId) throws IOException
	{
		synchronized (this)
		{
			cacheKeysByNpc.remove(npcId);
		}
		writeIndex();
	}

	private Path cachePath(String cacheKey)
	{
		return cacheDirectory.resolve(cacheKey + ".json");
	}

	private static boolean isValidCacheKey(String cacheKey)
	{
		return cacheKey != null && !cacheKey.isEmpty() && cacheKey.matches("[A-Za-z0-9._-]+");
	}

	private static boolean matchesSearchTerm(NpcCombatInfo info, String normalizedSearchTerm)
	{
		return normalizedSearchTerm.equals(normalizeSearchTerm(info.getDisplayName()))
			|| normalizedSearchTerm.equals(normalizeSearchTerm(info.getWikiPage()));
	}

	private static String normalizeSearchTerm(String value)
	{
		return value == null
			? ""
			: value.replace('_', ' ')
				.replace('\u00A0', ' ')
				.trim()
				.replaceAll("\\s+", " ")
				.toLowerCase(Locale.ENGLISH);
	}
}

package com.inspect.npc;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

class NpcInspectParser
{
	private static final Pattern WIKI_LINK = Pattern.compile("\\[\\[([^]|]+\\|)?([^]]+)]]");
	private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");
	private static final Pattern TEMPLATE = Pattern.compile("\\{\\{([^{}|]+\\|)?([^{}|]+)}}");
	private static final Pattern ITEM_TEMPLATE_LINK = Pattern.compile("\\{\\{(?:plink|ilink|item)\\|([^}|]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern DROP_LINE = Pattern.compile("\\|name\\s*=\\s*([^\\n|}]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern DROPS_HEADING = Pattern.compile("(?im)^==[ \\t]*Drops[ \\t]*==[ \\t]*$");
	private static final Pattern LEVEL_TWO_HEADING = Pattern.compile("(?m)^==(?!=)[^\\r\\n]*?(?<![=])==[ \\t]*$");
	private static final Pattern ITEM_REQUIREMENT_CUE = Pattern.compile("\\b(?:must|need(?:ed)?|requires?|required|use|without)\\b", Pattern.CASE_INSENSITIVE);
	private static final Pattern ITEM_REQUIREMENT_TARGET = Pattern.compile("\\b(?:kill(?:ing)?|finish(?:ing)?|defeat(?:ing)?|slay(?:ing)?)\\b", Pattern.CASE_INSENSITIVE);

	NpcCombatInfo parse(int npcId, String fallbackName, NpcWikiLookup lookup, String wikitext)
	{
		Map<String, String> fields = matchingFields(npcId, lookup.getAnchor(), wikitext);
		if (fields == null)
		{
			return null;
		}
		String suffix = selectVersionSuffix(npcId, lookup.getAnchor(), fields);
		if (suffix == null)
		{
			return null;
		}
		int resolvedNpcId = npcId >= 0 ? npcId : parseFirstId(value(fields, "id", suffix, null));

		return NpcCombatInfo.builder()
			.npcId(resolvedNpcId)
			.wikiPage(lookup.getPage())
			.wikiAnchor(lookup.getAnchor())
			.displayName(value(fields, "name", suffix, fallbackName))
			.combatLevel(value(fields, "combat", suffix, null))
			.xpBonus(value(fields, "xpbonus", suffix, null))
			.maxHit(value(fields, "max hit", suffix, null))
			.aggressive(value(fields, "aggressive", suffix, null))
			.poisonous(value(fields, "poisonous", suffix, null))
			.attackStyle(value(fields, "attack style", suffix, null))
			.attackSpeed(value(fields, "attack speed", suffix, null))
			.respawnTime(formatTicks(value(fields, "respawn", suffix, null)))
			.hitpoints(value(fields, "hitpoints", suffix, null))
			.attack(value(fields, "att", suffix, null))
			.strength(value(fields, "str", suffix, null))
			.defence(value(fields, "def", suffix, null))
			.magic(value(fields, "mage", suffix, null))
			.ranged(value(fields, "range", suffix, null))
			.attackBonus(value(fields, "attbns", suffix, null))
			.strengthBonus(value(fields, "strbns", suffix, null))
			.magicAttack(value(fields, "amagic", suffix, null))
			.magicStrength(value(fields, "mbns", suffix, null))
			.rangedAttack(value(fields, "arange", suffix, null))
			.rangedStrength(value(fields, "rngbns", suffix, null))
			.stabDefence(value(fields, "dstab", suffix, null))
			.slashDefence(value(fields, "dslash", suffix, null))
			.crushDefence(value(fields, "dcrush", suffix, null))
			.magicDefence(value(fields, "dmagic", suffix, null))
			.elementalWeaknessType(value(fields, "elementalweaknesstype", suffix, null))
			.elementalWeakness(value(fields, "elementalweaknesspercent", suffix, "No elemental weakness"))
			.lightRangedDefence(value(fields, "dlight", suffix, null))
			.standardRangedDefence(value(fields, "dstandard", suffix, null))
			.heavyRangedDefence(value(fields, "dheavy", suffix, null))
			.poisonResistance(formatResistance(value(fields, "poisonresistance", suffix, null)))
			.venomResistance(formatResistance(value(fields, "venomresistance", suffix, null)))
			.cannonImmunity(formatImmunity(value(fields, "immunecannon", suffix, null)))
			.thrallImmunity(formatImmunity(value(fields, "immunethrall", suffix, null)))
			.slayerLevel(value(fields, "slaylvl", suffix, null))
			.slayerCategory(firstNonEmpty(
				value(fields, "cat", suffix, null),
				value(fields, "slaycat", suffix, null),
				value(fields, "assignedby", suffix, null)
			))
			.assignedBy(value(fields, "assignedby", suffix, null))
			.taskOnly(firstNonEmpty(value(fields, "taskonly", suffix, null), value(fields, "task only", suffix, null)))
			.superiorVariant(firstNonEmpty(
				value(fields, "superior", suffix, null),
				value(fields, "superior monster", suffix, null)
			))
			.notableDrops(dropSummary(wikitext, "uncommon", "rare", "very rare"))
			.rareDrops(classifiedDrops(wikitext, DropCategory.RARE))
			.valuableDrops(classifiedDrops(wikitext, DropCategory.VALUABLE))
			.slayerOnlyDrops(classifiedDrops(wikitext, DropCategory.SLAYER_ONLY))
			.uniqueDrops(classifiedDrops(wikitext, DropCategory.UNIQUE))
			.alchableDrops(classifiedDrops(wikitext, DropCategory.ALCHABLE))
			.clueDrops(classifiedDrops(wikitext, DropCategory.CLUE))
			.ironmanDrops(classifiedDrops(wikitext, DropCategory.IRONMAN))
			.upgradeDrops(classifiedDrops(wikitext, DropCategory.UPGRADE))
			.resourceDrops(classifiedDrops(wikitext, DropCategory.RESOURCE))
			.supplyDrops(classifiedDrops(wikitext, DropCategory.SUPPLY))
			.itemRequirements(itemRequirements(wikitext))
			.fetchedAtEpochSecond(Instant.now().getEpochSecond())
			.sourceUrl(lookup.getSourceUrl())
			.build();
	}

	static String extractInfobox(String wikitext)
	{
		int start = wikitext.indexOf("{{Infobox Monster");
		if (start < 0)
		{
			return null;
		}

		return extractInfobox(wikitext, start);
	}

	private static String extractInfobox(String wikitext, int start)
	{
		int depth = 0;
		for (int i = start; i < wikitext.length() - 1; i++)
		{
			String token = wikitext.substring(i, i + 2);
			if ("{{".equals(token))
			{
				depth++;
				i++;
			}
			else if ("}}".equals(token))
			{
				depth--;
				i++;
				if (depth == 0)
				{
					return wikitext.substring(start, i + 1);
				}
			}
		}

		return null;
	}

	private static Map<String, String> matchingFields(int npcId, String anchor, String wikitext)
	{
		for (String infobox : extractInfoboxes(wikitext))
		{
			Map<String, String> fields = parseFields(infobox);
			if (selectVersionSuffix(npcId, anchor, fields) != null)
			{
				return fields;
			}
		}
		return null;
	}

	private static List<String> extractInfoboxes(String wikitext)
	{
		List<String> infoboxes = new ArrayList<>();
		int searchFrom = 0;
		while (searchFrom < wikitext.length())
		{
			int start = wikitext.indexOf("{{Infobox Monster", searchFrom);
			if (start < 0)
			{
				break;
			}

			String infobox = extractInfobox(wikitext, start);
			if (infobox == null)
			{
				break;
			}

			infoboxes.add(infobox);
			searchFrom = start + infobox.length();
		}
		return infoboxes;
	}

	static Map<String, String> parseFields(String infobox)
	{
		Map<String, String> fields = new LinkedHashMap<>();
		String infoboxBody = infobox.endsWith("}}") ? infobox.substring(0, infobox.length() - 2) : infobox;
		for (String part : splitTopLevel(infoboxBody))
		{
			part = part.trim();
			int equals = part.indexOf('=');
			if (equals <= 0)
			{
				continue;
			}

			String key = part.substring(0, equals).trim().toLowerCase();
			String value = normalizeValue(part.substring(equals + 1).trim());
			if (!key.isEmpty())
			{
				fields.put(key, value);
			}
		}
		return fields;
	}

	private static String selectVersionSuffix(int npcId, String anchor, Map<String, String> fields)
	{
		if (npcId < 0)
		{
			String anchorSuffix = selectVersionSuffixByAnchor(anchor, fields);
			if (anchorSuffix != null)
			{
				return anchorSuffix;
			}

			if (fields.containsKey("id") || !fields.containsKey("version1"))
			{
				return "";
			}
			return "1";
		}

		String id = Integer.toString(npcId);
		for (Map.Entry<String, String> entry : fields.entrySet())
		{
			String key = entry.getKey();
			if (!key.matches("id\\d*"))
			{
				continue;
			}

			for (String candidate : entry.getValue().split(","))
			{
				if (id.equals(candidate.trim()))
				{
					return key.substring(2);
				}
			}
		}

		String anchorSuffix = selectVersionSuffixByAnchor(anchor, fields);
		if (anchorSuffix != null)
		{
			return anchorSuffix;
		}

		return fields.containsKey("id") || !fields.containsKey("version1") ? "" : null;
	}

	private static String selectVersionSuffixByAnchor(String anchor, Map<String, String> fields)
	{
		if (anchor == null)
		{
			return null;
		}

		String normalizedAnchor = anchor.replace('_', ' ').trim();
		for (Map.Entry<String, String> entry : fields.entrySet())
		{
			if (entry.getKey().startsWith("version") && normalizedAnchor.equalsIgnoreCase(entry.getValue()))
			{
				return entry.getKey().substring("version".length());
			}
		}
		return null;
	}

	private static int parseFirstId(String value)
	{
		if (value == null)
		{
			return -1;
		}

		for (String candidate : value.split(","))
		{
			String trimmed = candidate.trim();
			if (trimmed.matches("\\d+"))
			{
				return Integer.parseInt(trimmed);
			}
		}
		return -1;
	}

	private static String value(Map<String, String> fields, String key, String suffix, String fallback)
	{
		String suffixed = fields.get(key + suffix);
		if (suffixed != null && !suffixed.isEmpty())
		{
			return suffixed;
		}

		String unsuffixed = fields.get(key);
		if (unsuffixed != null && !unsuffixed.isEmpty())
		{
			return unsuffixed;
		}

		return fallback;
	}

	private static String normalizeValue(String value)
	{
		String normalized = value.replace("&nbsp;", " ").replace("&#160;", " ");
		Matcher linkMatcher = WIKI_LINK.matcher(normalized);
		StringBuilder linkBuffer = new StringBuilder();
		while (linkMatcher.find())
		{
			linkMatcher.appendReplacement(linkBuffer, Matcher.quoteReplacement(linkMatcher.group(2)));
		}
		linkMatcher.appendTail(linkBuffer);

		return HTML_TAG.matcher(normalizeTemplates(linkBuffer.toString()))
			.replaceAll("")
			.replace("'''", "")
			.replace("''", "")
			.trim();
	}

	private static String normalizeTemplates(String value)
	{
		String normalized = value;
		while (true)
		{
			Matcher matcher = TEMPLATE.matcher(normalized);
			if (!matcher.find())
			{
				return normalized;
			}

			StringBuilder buffer = new StringBuilder();
			do
			{
				matcher.appendReplacement(buffer, Matcher.quoteReplacement(matcher.group(2)));
			}
			while (matcher.find());
			matcher.appendTail(buffer);
			normalized = buffer.toString();
		}
	}

	private static String formatTicks(String value)
	{
		if (value == null || !value.matches("\\d+"))
		{
			return value;
		}

		int ticks = Integer.parseInt(value);
		double seconds = ticks * 0.6d;
		String secondsText = seconds == Math.rint(seconds) ? Integer.toString((int) seconds) : String.format(Locale.ENGLISH, "%.1f", seconds);
		return ticks + " ticks (" + secondsText + " seconds)";
	}

	private static String formatResistance(String value)
	{
		if (value == null || value.contains("%"))
		{
			return value;
		}

		return value + "% resistance";
	}

	private static String formatImmunity(String value)
	{
		if (value == null)
		{
			return null;
		}

		if ("yes".equalsIgnoreCase(value))
		{
			return "Immune";
		}

		if ("no".equalsIgnoreCase(value))
		{
			return "Not immune";
		}

		return value;
	}

	private static String firstNonEmpty(String... values)
	{
		for (String value : values)
		{
			if (value != null && !value.isEmpty())
			{
				return value;
			}
		}
		return null;
	}

	private static String dropSummary(String wikitext, String... rarityTokens)
	{
		String drops = dropSection(wikitext);
		if (drops == null)
		{
			return null;
		}

		List<String> names = new ArrayList<>();
		Matcher matcher = DROP_LINE.matcher(drops);
		while (matcher.find() && names.size() < 6)
		{
			int lineStart = Math.max(0, drops.lastIndexOf('\n', matcher.start()));
			int lineEnd = drops.indexOf('\n', matcher.end());
			String line = drops.substring(lineStart, lineEnd < 0 ? drops.length() : lineEnd).toLowerCase();
			if (!containsAny(line, rarityTokens))
			{
				continue;
			}

			String name = normalizeValue(matcher.group(1));
			if (!name.isEmpty() && !names.contains(name))
			{
				names.add(name);
			}
		}
		return names.isEmpty() ? null : String.join(", ", names);
	}

	private static boolean containsAny(String value, String... tokens)
	{
		for (String token : tokens)
		{
			if (value.contains(token))
			{
				return true;
			}
		}
		return false;
	}

	private static List<NpcItemRequirement> itemRequirements(String wikitext)
	{
		if (wikitext == null || wikitext.isEmpty())
		{
			return Collections.emptyList();
		}

		List<NpcItemRequirement> requirements = new ArrayList<>();
		Set<String> seenLabels = new LinkedHashSet<>();
		for (String sentence : wikitext.split("(?<=[.!?])\\s+|\\r?\\n+"))
		{
			String normalizedSentence = normalizeValue(sentence);
			if (!isItemRequirementSentence(normalizedSentence))
			{
				continue;
			}

			List<String> alternatives = itemRequirementAlternatives(sentence);
			if (alternatives.isEmpty())
			{
				continue;
			}

			String label = String.join(" or ", alternatives);
			String normalizedLabel = label.toLowerCase(Locale.ENGLISH);
			if (seenLabels.add(normalizedLabel))
			{
				requirements.add(new NpcItemRequirement(label, alternatives));
			}
		}
		return requirements.isEmpty() ? Collections.emptyList() : requirements;
	}

	private static boolean isItemRequirementSentence(String sentence)
	{
		String lower = sentence.toLowerCase(Locale.ENGLISH);
		if (containsAny(lower,
			"not required",
			"not need",
			"not needed",
			"not necessary",
			"no requirement",
			"without needing"))
		{
			return false;
		}

		return ITEM_REQUIREMENT_CUE.matcher(sentence).find()
			&& ITEM_REQUIREMENT_TARGET.matcher(sentence).find();
	}

	private static List<String> itemRequirementAlternatives(String sentence)
	{
		List<String> alternatives = new ArrayList<>();
		addItemRequirementLinks(alternatives, sentence);
		addItemRequirementTemplates(alternatives, sentence);
		addKnownItemRequirementAlternatives(alternatives, sentence);
		return alternatives;
	}

	private static void addKnownItemRequirementAlternatives(List<String> alternatives, String sentence)
	{
		String lower = sentence.toLowerCase(Locale.ENGLISH);
		if (lower.contains("gargoyle") && containsAnyItem(alternatives, "rock hammer", "rock thrownhammer", "granite hammer"))
		{
			addItemRequirementAlternative(alternatives, "Granite maul");
		}
	}

	private static boolean containsAnyItem(List<String> items, String... names)
	{
		for (String item : items)
		{
			for (String name : names)
			{
				if (item.equalsIgnoreCase(name))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static void addItemRequirementLinks(List<String> alternatives, String sentence)
	{
		Matcher matcher = WIKI_LINK.matcher(sentence);
		while (matcher.find())
		{
			addItemRequirementAlternative(alternatives, matcher.group(2));
		}
	}

	private static void addItemRequirementTemplates(List<String> alternatives, String sentence)
	{
		Matcher matcher = ITEM_TEMPLATE_LINK.matcher(sentence);
		while (matcher.find())
		{
			addItemRequirementAlternative(alternatives, matcher.group(1));
		}
	}

	private static void addItemRequirementAlternative(List<String> alternatives, String value)
	{
		String name = normalizeValue(value).replace('_', ' ').trim();
		if (!isLikelyItemRequirement(name))
		{
			return;
		}

		for (String existing : alternatives)
		{
			if (existing.equalsIgnoreCase(name))
			{
				return;
			}
		}
		alternatives.add(name);
	}

	private static boolean isLikelyItemRequirement(String name)
	{
		if (name == null || name.isEmpty() || name.length() > 48)
		{
			return false;
		}

		String lower = name.toLowerCase(Locale.ENGLISH);
		return !containsAny(lower, "slayer", "hitpoints", "attack", "strength", "defence", "ranged", "magic", "prayer", "combat", "smasher");
	}

	private static String classifiedDrops(String wikitext, DropCategory category)
	{
		String drops = dropSection(wikitext);
		if (drops == null)
		{
			return null;
		}

		List<String> matching = new ArrayList<>();
		Matcher matcher = DROP_LINE.matcher(drops);
		while (matcher.find())
		{
			String drop = normalizeValue(matcher.group(1));
			String context = dropContext(drops, matcher.start(), matcher.end());
			if (!drop.isEmpty() && category.matches(drop, context) && !matching.contains(drop))
			{
				matching.add(drop);
				if (matching.size() >= 6)
				{
					break;
				}
			}
		}
		return matching.isEmpty() ? null : String.join(", ", matching);
	}

	private static String dropContext(String drops, int matchStart, int matchEnd)
	{
		int lineStart = Math.max(0, drops.lastIndexOf('\n', matchStart));
		int lineEnd = drops.indexOf('\n', matchEnd);
		String line = drops.substring(lineStart, lineEnd < 0 ? drops.length() : lineEnd);

		String heading = "";
		Matcher headingMatcher = Pattern.compile("(?m)^===[^\\r\\n]*===[ \\t]*$").matcher(drops);
		while (headingMatcher.find() && headingMatcher.start() < matchStart)
		{
			heading = headingMatcher.group();
		}
		return (heading + " " + line).toLowerCase(Locale.ENGLISH);
	}

	private static List<String> dropNames(String wikitext)
	{
		String drops = dropSection(wikitext);
		if (drops == null)
		{
			return java.util.Collections.emptyList();
		}

		List<String> names = new ArrayList<>();
		Matcher matcher = DROP_LINE.matcher(drops);
		while (matcher.find() && names.size() < 30)
		{
			String name = normalizeValue(matcher.group(1));
			if (!name.isEmpty() && !names.contains(name))
			{
				names.add(name);
			}
		}
		return names;
	}

	private static String dropSection(String wikitext)
	{
		Matcher dropsHeading = DROPS_HEADING.matcher(wikitext);
		if (!dropsHeading.find())
		{
			return null;
		}

		int start = dropsHeading.end();
		Matcher nextHeading = LEVEL_TWO_HEADING.matcher(wikitext);
		int end = nextHeading.find(start) ? nextHeading.start() : wikitext.length();
		return wikitext.substring(start, end);
	}

	private enum DropCategory
	{
		VALUABLE
			{
				@Override
				boolean matches(String drop, String context)
				{
					return RARE.matches(drop, context) || UNIQUE.matches(drop, context) || ALCHABLE.matches(drop, context);
				}
			},
		RARE
			{
				@Override
				boolean matches(String drop, String context)
				{
					return containsAny(context, "rare", "very rare") || numericRarityDenominator(context) >= 128;
				}
			},
		SLAYER_ONLY
			{
				@Override
				boolean matches(String drop, String context)
				{
					return containsAny(context, "slayer", "task only", "on task", "task-only");
				}
			},
		UNIQUE
			{
				@Override
				boolean matches(String drop, String context)
				{
					String lower = drop.toLowerCase(Locale.ENGLISH);
					return lower.contains("clue") || lower.contains("key") || lower.contains("shard") || lower.contains("sigil")
						|| lower.contains("pet") || lower.contains("visage") || lower.contains("head") || lower.contains("unique");
				}
			},
		ALCHABLE
			{
				@Override
				boolean matches(String drop, String context)
				{
					String lower = drop.toLowerCase(Locale.ENGLISH);
					return lower.contains("rune ") || lower.contains("dragon ") || lower.contains("adamant ")
						|| lower.contains("mithril ") || lower.contains("battleaxe") || lower.contains("platebody")
						|| lower.contains("kiteshield") || lower.contains("longsword");
				}
			},
		CLUE
			{
				@Override
				boolean matches(String drop, String context)
				{
					return drop.toLowerCase(Locale.ENGLISH).contains("clue");
				}
			},
		IRONMAN
			{
				@Override
				boolean matches(String drop, String context)
				{
					return RESOURCE.matches(drop, context) || SUPPLY.matches(drop, context) || UPGRADE.matches(drop, context);
				}
			},
		UPGRADE
			{
				@Override
				boolean matches(String drop, String context)
				{
					String lower = drop.toLowerCase(Locale.ENGLISH);
					return containsAny(lower, "upgrade", "attachment", "shard", "sigil", "visage", "hilt", "claw",
						"fang", "jaw", "heart", "gem", "dust", "clamp", "needle", "thread", "totem", "head");
				}
			},
		RESOURCE
			{
				@Override
				boolean matches(String drop, String context)
				{
					String lower = drop.toLowerCase(Locale.ENGLISH);
					return lower.contains("ore") || lower.contains("log") || lower.contains("bar") || lower.contains("herb")
						|| lower.startsWith("grimy ") || lower.contains(" weed") || lower.contains("seed")
						|| lower.contains("hide") || lower.contains("scale") || lower.contains("essence");
				}
			},
		SUPPLY
			{
				@Override
				boolean matches(String drop, String context)
				{
					String lower = drop.toLowerCase(Locale.ENGLISH);
					return lower.contains("bone") || lower.contains("rune") || lower.contains("arrow") || lower.contains("bolt")
						|| lower.contains("food") || lower.contains("shark") || lower.contains("lobster")
						|| lower.contains("potion") || lower.contains("ammo");
				}
			};

		abstract boolean matches(String drop, String context);
	}

	private static int numericRarityDenominator(String context)
	{
		Matcher matcher = Pattern.compile("1\\s*/\\s*(\\d+)").matcher(context);
		if (!matcher.find())
		{
			return 0;
		}

		try
		{
			return Integer.parseInt(matcher.group(1));
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}

	private static Iterable<String> splitTopLevel(String infobox)
	{
		Map<Integer, String> parts = new LinkedHashMap<>();
		int depth = 0;
		int linkDepth = 0;
		int start = 0;
		int index = 0;
		for (int i = 0; i < infobox.length(); i++)
		{
			if (i < infobox.length() - 1 && "[[".equals(infobox.substring(i, i + 2)))
			{
				linkDepth++;
				i++;
				continue;
			}
			if (i < infobox.length() - 1 && "]]".equals(infobox.substring(i, i + 2)))
			{
				linkDepth = Math.max(0, linkDepth - 1);
				i++;
				continue;
			}
			if (i < infobox.length() - 1 && "{{".equals(infobox.substring(i, i + 2)))
			{
				depth++;
				i++;
				continue;
			}
			if (i < infobox.length() - 1 && "}}".equals(infobox.substring(i, i + 2)))
			{
				depth = Math.max(0, depth - 1);
				i++;
				continue;
			}
			if (infobox.charAt(i) == '|' && depth == 1 && linkDepth == 0)
			{
				parts.put(index++, infobox.substring(start, i));
				start = i + 1;
			}
		}
		parts.put(index, infobox.substring(start));
		return parts.values();
	}
}

