@Value
@Builder
public class NpcCombatInfo
{
	public static final int CACHE_SCHEMA_VERSION = 2;

	int npcId;
	@Builder.Default
	int cacheSchemaVersion = CACHE_SCHEMA_VERSION;
	String wikiPage;
	String wikiAnchor;
	String displayName;
	String combatLevel;
	String xpBonus;
	String maxHit;
	String aggressive;
	String poisonous;
	String attackStyle;
	String attackSpeed;
	String respawnTime;
	String hitpoints;
	String attack;
	String strength;
	String defence;
	String magic;
	String ranged;
	String attackBonus;
	String strengthBonus;
	String magicAttack;
	String magicStrength;
	String rangedAttack;
	String rangedStrength;
	String stabDefence;
	String slashDefence;
	String crushDefence;
	String magicDefence;
	String elementalWeaknessType;
	String elementalWeakness;
	String lightRangedDefence;
	String standardRangedDefence;
	String heavyRangedDefence;
	String poisonResistance;
	String venomResistance;
	String cannonImmunity;
	String thrallImmunity;
	String slayerLevel;
	String slayerCategory;
	String superiorVariant;
	String notableDrops;
	String rareDrops;
	String valuableDrops;
	String slayerOnlyDrops;
	String uniqueDrops;
	String alchableDrops;
	String clueDrops;
	String ironmanDrops;
	String upgradeDrops;
	String resourceDrops;
	String supplyDrops;
	String assignedBy;
	String taskOnly;
	@Builder.Default
	List<NpcItemRequirement> itemRequirements = java.util.Collections.emptyList();
	long fetchedAtEpochSecond;
	String sourceUrl;

	public String cacheKey()
	{
		String page = wikiPage == null ? "unknown" : wikiPage;
		String anchor = wikiAnchor == null ? "default" : wikiAnchor;
		return npcId + "-" + sanitize(page) + "-" + sanitize(anchor);
	}

	public boolean isExpired(long nowEpochSecond, int ttlDays)
	{
		if (ttlDays <= 0)
		{
			return true;
		}

		long ttlSeconds = ttlDays * 24L * 60L * 60L;
		return nowEpochSecond - fetchedAtEpochSecond > ttlSeconds;
	}

	public boolean hasCurrentCacheSchema()
	{
		return cacheSchemaVersion == CACHE_SCHEMA_VERSION;
	}

	private static String sanitize(String value)
	{
		StringBuilder builder = new StringBuilder(value.length());
		for (int i = 0; i < value.length(); i++)
		{
			char c = value.charAt(i);
			builder.append(Character.isLetterOrDigit(c) ? Character.toLowerCase(c) : '-');
		}
		return builder.toString().replaceAll("-+", "-").replaceAll("^-|-$", "");
	}

	public String valueOrDash(String value)
	{
		return Objects.toString(value, "--");
	}
}

package com.inspect.npc;

import com.inspect.item.ItemInspectInfo;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

@Value
public class EquipmentRecommendation
{
	NpcCombatInfo npc;
	CombatStyleRecommendation style;
	List<RecommendedItem> items;

	public String getStyleName()
	{
		return style == null ? null : style.getDisplayName();
	}

	public String getDefenceLabel()
	{
		return style == null ? null : style.getDefenceLabel();
	}

	public boolean hasItems()
	{
		return items != null && !items.isEmpty();
	}

	public Set<Integer> itemIds()
	{
		Set<Integer> itemIds = new HashSet<>();
		if (items != null)
		{
			for (RecommendedItem item : items)
			{
				itemIds.add(item.getItemId());
			}
		}
		return itemIds;
	}

	public Map<Integer, Integer> bankItemRanks()
	{
		Map<Integer, Integer> ranks = new LinkedHashMap<>();
		if (items != null)
		{
			for (RecommendedItem item : items)
			{
				if (item.isInBank())
				{
					ranks.put(item.getItemId(), item.getRank());
				}
			}
		}
		return ranks;
	}

	public static EquipmentRecommendation preview(NpcCombatInfo npc)
	{
		return new EquipmentRecommendation(npc, CombatStyleRecommendation.forNpc(npc), Collections.emptyList());
	}

	static EquipmentRecommendation fromBank(NpcCombatInfo npc, Collection<ItemInspectInfo> bankItems, int limit)
	{
		List<CandidateItem> candidates = new ArrayList<>();
		for (ItemInspectInfo item : bankItems)
		{
			candidates.add(new CandidateItem(item, true, false));
		}
		return fromCandidates(npc, candidates, limit);
	}

	static EquipmentRecommendation fromCandidates(NpcCombatInfo npc, Collection<CandidateItem> candidates, int limit)
	{
		CombatStyleRecommendation style = CombatStyleRecommendation.forNpc(npc);
		if (style == null)
		{
			return new EquipmentRecommendation(npc, null, Collections.emptyList());
		}

		List<RecommendedItem> recommendations = new ArrayList<>();
		for (CandidateItem candidate : candidates)
		{
			ItemInspectInfo item = candidate.getInfo();
			if (item == null || !style.isRelevant(item))
			{
				continue;
			}

			recommendations.add(new RecommendedItem(
				item.getItemId(),
				item.getDisplayName(),
				item.getSlot(),
				style.score(item),
				candidate.isInBank(),
				candidate.isEquipped(),
				0
			));
		}

		recommendations.sort(Comparator
			.comparingDouble(RecommendedItem::getScore)
			.reversed()
			.thenComparing(RecommendedItem::getDisplayName, Comparator.nullsLast(String::compareToIgnoreCase)));

		int boundedLimit = Math.max(0, limit);
		if (recommendations.size() > boundedLimit)
		{
			recommendations = new ArrayList<>(recommendations.subList(0, boundedLimit));
		}

		for (int i = 0; i < recommendations.size(); i++)
		{
			RecommendedItem item = recommendations.get(i);
			recommendations.set(i, new RecommendedItem(
				item.getItemId(),
				item.getDisplayName(),
				item.getSlot(),
				item.getScore(),
				item.isInBank(),
				item.isEquipped(),
				i + 1
			));
		}

		return new EquipmentRecommendation(npc, style, Collections.unmodifiableList(recommendations));
	}

	@Value
	static class CandidateItem
	{
		ItemInspectInfo info;
		boolean inBank;
		boolean equipped;
	}

	@Value
	public static class RecommendedItem
	{
		int itemId;
		String displayName;
		String slot;
		double score;
		boolean inBank;
		boolean equipped;
		int rank;
	}
}

